package com.etiennelawlor.eggday

import java.io.File
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The dot-matrix digit drawables are generated by scripts/generate_art.py. This checks each
 * one still draws the expected dots, so a hand edit or a stale regeneration gets caught.
 */
class DotMatrixTest {

    // Same 5x7 glyphs as GLYPHS in scripts/generate_art.py.
    private val glyphs = mapOf(
        '0' to listOf("01110", "10001", "10001", "10001", "10001", "10001", "01110"),
        '1' to listOf("00100", "01100", "00100", "00100", "00100", "00100", "01110"),
        '2' to listOf("01110", "10001", "00001", "00010", "00100", "01000", "11111"),
        '3' to listOf("11111", "00010", "00100", "00010", "00001", "10001", "01110"),
        '4' to listOf("00010", "00110", "01010", "10010", "11111", "00010", "00010"),
        '5' to listOf("11111", "10000", "11110", "00001", "00001", "10001", "01110"),
        '6' to listOf("00110", "01000", "10000", "11110", "10001", "10001", "01110"),
        '7' to listOf("11111", "00001", "00010", "00100", "01000", "01000", "01000"),
        '8' to listOf("01110", "10001", "10001", "01110", "10001", "10001", "01110"),
        '9' to listOf("01110", "10001", "10001", "01111", "00001", "00010", "01100"),
    )

    // Unit tests run with the app module as the working directory.
    private fun drawable(name: String) = File("src/main/res/drawable/$name.xml")

    @Test
    fun everyDigitHasADrawable() {
        for (digit in '0'..'9') {
            assertTrue("dm_$digit.xml is missing", drawable("dm_$digit").exists())
        }
        assertEquals(10, EggArt.DIGITS.size)
    }

    @Test
    fun digitDrawablesMatchGlyphs() {
        // Each dot is "M<x>,<y> a..." where x is its left edge; recover grid cells from them.
        val dotStart = Regex("""M([\d.]+),([\d.]+) a""")
        for ((digit, rows) in glyphs) {
            val pathData = drawable("dm_$digit").readText()
            val cells = dotStart.findAll(pathData).map { match ->
                val left = match.groupValues[1].toDouble()
                val centerY = match.groupValues[2].toDouble()
                Pair(Math.round(left + 0.42 - 0.5).toInt(), Math.round(centerY - 0.5).toInt())
            }.toSet()
            val expected = rows.flatMapIndexed { row, bits ->
                bits.mapIndexedNotNull { col, bit -> if (bit == '1') Pair(col, row) else null }
            }.toSet()
            assertEquals("dm_$digit.xml dots", expected, cells)
        }
    }
}
